async function guardarNuevoProducto(evento) {
    evento.preventDefault();

    // Captura los valores de tus inputs del formulario de admin
    const nuevoProducto = {
        nombre: document.getElementById('nombreProducto').value,
        categoria: document.getElementById('categoriaProducto').value,
        precio: Number(document.getElementById('precioProducto').value),
        imagen: document.getElementById('imagenProducto').value
    };

    try {
        const respuesta = await fetch('http://localhost:5000/api/productos', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(nuevoProducto)
        });

        if (respuesta.ok) {
            alert('¡Producto guardado y registrado en el servidor con éxito!');
            cargarProductos(); // Recarga la lista
        }
    } catch (error) {
        console.error("Error al guardar el producto:", error);
    }
}